   SET "版本" = 73,
       "脚本" = '073_mobile_push_gateway_and_performance_formula_engine.sql',
       "检查摘要" = '新增移动协同推送网关、科研绩效动态公式测算器与自定义国考年报引擎',
       "应用时间" = CURRENT_TIMESTAMP
 WHERE "编号" = 1;

